/**
 * Telegram Bot API helpers — the outbound HTTP wrapper.
 *
 * We're multi-tenant with per-user bots, so these helpers take the bot
 * token as an explicit argument (there is no service-wide token anymore).
 * `notifyTenant` in lib/telegram.ts is the normal entrypoint — it looks up
 * the per-user bot doc, decrypts the token, and calls `sendMessageWithToken`.
 * The webhook handler uses `sendMessageWithToken` directly since it already
 * has the token in hand from the bot-doc lookup.
 *
 * Errors are logged but never thrown — a failed Telegram reply must not
 * turn a webhook response into a 500 (Telegram retries 500s, which would
 * flood us).
 */


export async function sendMessageWithToken(
  botToken: string,
  chatId: number,
  text: string,
): Promise<boolean> {
  if (!botToken) return false;
  try {
    const res = await fetch(`https://api.telegram.org/bot${botToken}/sendMessage`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ chat_id: chatId, text }),
      signal: AbortSignal.timeout(5000),
    });
    if (!res.ok) {
      console.error(
        JSON.stringify({
          severity: 'WARNING',
          msg: 'telegram.sendMessage_http_error',
          chatId,
          status: res.status,
        }),
      );
      return false;
    }
    return true;
  } catch (e) {
    console.error(
      JSON.stringify({
        severity: 'WARNING',
        msg: 'telegram.sendMessage_failed',
        chatId,
        err: (e as Error).message,
      }),
    );
    return false;
  }
}

/**
 * Register a webhook URL with Telegram. Called automatically when the user
 * saves a bot token so they never have to run setWebhook manually.
 * Returns true on success, false + logs on failure (non-fatal — the token
 * is still persisted; the user can retry by re-saving).
 */
export async function setWebhook(botToken: string, url: string): Promise<boolean> {
  try {
    const res = await fetch(`https://api.telegram.org/bot${botToken}/setWebhook`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ url }),
      signal: AbortSignal.timeout(8000),
    });
    const body = (await res.json()) as { ok: boolean; description?: string };
    if (!body.ok) {
      console.error(
        JSON.stringify({
          severity: 'WARNING',
          msg: 'telegram.setWebhook_failed',
          description: body.description,
        }),
      );
      return false;
    }
    return true;
  } catch (e) {
    console.error(
      JSON.stringify({
        severity: 'WARNING',
        msg: 'telegram.setWebhook_error',
        err: (e as Error).message,
      }),
    );
    return false;
  }
}

/**
 * One-shot probe: ask Telegram for the bot's own profile. Used when the
 * user saves a new bot token so we can confirm the token is valid (and
 * surface the @username it actually belongs to) before persisting.
 *
 * Returns null on any failure — never throws.
 */
export async function getBotProfile(
  botToken: string,
): Promise<{ id: number; username: string } | null> {
  try {
    const res = await fetch(`https://api.telegram.org/bot${botToken}/getMe`, {
      method: 'GET',
      signal: AbortSignal.timeout(5000),
    });
    if (!res.ok) return null;
    const body = (await res.json()) as {
      ok: boolean;
      result?: { id: number; username?: string };
    };
    if (!body.ok || !body.result?.username) return null;
    return { id: body.result.id, username: body.result.username };
  } catch {
    return null;
  }
}

/**
 * What Telegram itself thinks of the bot's webhook. Lets the settings UI
 * surface "is the URL Telegram has the one I expect?", "are updates piling
 * up?", and "did my webhook return an error last time Telegram tried?" —
 * without which a broken webhook looks indistinguishable from a bot that
 * just isn't replying.
 *
 * Returns null on any failure — never throws.
 */
export interface WebhookInfo {
  url: string;
  pendingUpdateCount: number;
  lastErrorDate?: string;
  lastErrorMessage?: string;
  ipAddress?: string;
  maxConnections?: number;
}

export async function getWebhookInfo(botToken: string): Promise<WebhookInfo | null> {
  try {
    const res = await fetch(`https://api.telegram.org/bot${botToken}/getWebhookInfo`, {
      method: 'GET',
      signal: AbortSignal.timeout(5000),
    });
    if (!res.ok) return null;
    const body = (await res.json()) as {
      ok: boolean;
      result?: {
        url: string;
        pending_update_count: number;
        last_error_date?: number;
        last_error_message?: string;
        ip_address?: string;
        max_connections?: number;
      };
    };
    if (!body.ok || !body.result) return null;
    const r = body.result;
    return {
      url: r.url,
      pendingUpdateCount: r.pending_update_count,
      lastErrorDate: r.last_error_date
        ? new Date(r.last_error_date * 1000).toISOString()
        : undefined,
      lastErrorMessage: r.last_error_message,
      ipAddress: r.ip_address,
      maxConnections: r.max_connections,
    };
  } catch {
    return null;
  }
}
